import { canonicalize } from "@hypit/hypit/protocol";
import { assertNarrativeAlignmentIdentity } from "./identity.js";
import { materializeSegmentBoundaryAlignment } from "./materialize.js";
import { narrativeTemporalProducers, narrativeTemporalTypes } from "./manifest.js";
import { createNarrativeProjection, projectNarrativeAlignment, projectNarrativeInstant } from "./projection.js";
function inline(value, subject) {
    if (value?.kind !== "inline")
        throw new Error(`${subject} must be inline`);
    return value.value;
}
export const narrativeTemporalComponent = {
    validators: [{ type: narrativeTemporalTypes.narrativeAlignment,
            handler: ({ value }) => assertNarrativeAlignmentIdentity(inline(value, "NarrativeAlignment")) }],
    producers: [{
            producer: narrativeTemporalProducers.materializeSegmentBoundaries,
            handler: ({ inputs }) => ({ outputs: { alignment: { kind: "inline", value: canonicalize(materializeSegmentBoundaryAlignment(inline(inputs.narrative?.value, "Narrative"), inline(inputs.segment?.value, "NarrativeSegmentRef"), inline(inputs.domain?.value, "LocalTemporalDomain"))) } }, needs: {} }),
        }, {
            producer: narrativeTemporalProducers.projectAlignment,
            handler: ({ inputs }) => ({ outputs: { parts: { kind: "inline", value: canonicalize({ parts: [
                                projectNarrativeAlignment(inline(inputs.alignment?.value, "NarrativeAlignment"), inline(inputs.domain?.value, "LocalTemporalDomain"), inline(inputs.window?.value, "TemporalWindow"), inline(inputs.timeline?.value, "Timeline")),
                            ] }) } }, needs: {} }),
        }, {
            producer: narrativeTemporalProducers.combineProjectionParts,
            handler: ({ inputs }) => {
                const left = inline(inputs.left?.value, "NarrativeProjectionParts");
                const right = inline(inputs.right?.value, "NarrativeProjectionParts");
                return { outputs: { parts: { kind: "inline", value: canonicalize({ parts: [...left.parts, ...right.parts] }) } }, needs: {} };
            },
        }, {
            producer: narrativeTemporalProducers.finalizeProjection,
            handler: ({ inputs }) => {
                const header = inline(inputs.header?.value, "NarrativeProjectionHeader");
                const narrative = inline(inputs.narrative?.value, "Narrative");
                const timeline = inline(inputs.timeline?.value, "Timeline");
                const parts = inline(inputs.parts?.value, "NarrativeProjectionParts");
                return { outputs: { projection: { kind: "inline", value: canonicalize(createNarrativeProjection(header.id, narrative.id, timeline, parts.parts)) } }, needs: {} };
            },
        }, ...([
            projectionFacet(narrativeTemporalProducers.projectSelectionInstant, "selection", "selection"),
            projectionFacet(narrativeTemporalProducers.projectSegmentInstant, "segment", "segment"),
            projectionFacet(narrativeTemporalProducers.projectMomentInstant, "moment", "moment"),
        ])],
};
function projectionFacet(producer, inputName, sourceKind) {
    return { producer, handler: ({ inputs }) => {
            const spec = inline(inputs.spec?.value, "NarrativeInstantSpec");
            return { outputs: { instant: { kind: "inline", value: canonicalize(projectNarrativeInstant({
                            narrative: inline(inputs.projection?.value, "NarrativeProjection"),
                            source: inline(inputs[inputName]?.value, inputName),
                            sourceKind, spec,
                        })) } }, needs: {} };
        } };
}
